conv_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

constexpr int kThreads = 256;
constexpr int kInChannels = 3;
constexpr int kOutChannels = 32;
constexpr int kKernel = 3;
constexpr int kTileOH = 32;
constexpr int kTileOW = 32;
constexpr int kTileIH = kTileOH + kKernel - 1;
constexpr int kTileIW = kTileOW + kKernel - 1;
constexpr int kPixelsPerThread = 4;
constexpr int kOutChannelBlock = 2;
constexpr int kSmemXElems = kInChannels * kTileIH * kTileIW;
constexpr int kSmemWElems = kOutChannels * kInChannels * kKernel * kKernel;

static_assert(kThreads * kPixelsPerThread == kTileOH * kTileOW,
              "Invalid thread-to-output mapping");
static_assert(kOutChannels % kOutChannelBlock == 0,
              "Output channel block must divide output channels");

__global__ void __launch_bounds__(kThreads, 1)
conv2d_bf16_k3_cin3_kernel(
    const __nv_bfloat16* __restrict__ X,
    const __nv_bfloat16* __restrict__ W,
    __nv_bfloat16* __restrict__ Y,
    int height_in,
    int width_in,
    int height_out,
    int width_out,
    int64_t x_batch_stride,
    int64_t y_batch_stride)
{
  const int tid = threadIdx.x;
  const int batch = blockIdx.z;
  const int out_h0 = blockIdx.y * kTileOH;
  const int out_w0 = blockIdx.x * kTileOW;

  const int64_t x_c_stride = (int64_t)height_in * width_in;
  const int64_t x_h_stride = (int64_t)width_in;
  const int64_t y_c_stride = (int64_t)height_out * width_out;
  const int64_t y_h_stride = (int64_t)width_out;

  // Global NCHW tensors represented with CuTe layouts.
  Tensor mX = make_tensor(
      make_gmem_ptr(X + (int64_t)batch * x_batch_stride),
      make_shape(Int<kInChannels>{}, height_in, width_in),
      make_stride(x_c_stride, x_h_stride, Int<1>{})
  );

  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Int<kOutChannels>{}, Int<kInChannels>{}, Int<kKernel>{}, Int<kKernel>{}),
      make_stride(Int<kInChannels * kKernel * kKernel>{},
                  Int<kKernel * kKernel>{},
                  Int<kKernel>{},
                  Int<1>{})
  );

  Tensor mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)batch * y_batch_stride),
      make_shape(Int<kOutChannels>{}, height_out, width_out),
      make_stride(y_c_stride, y_h_stride, Int<1>{})
  );

  // Shared tiles are stored as float to make the inner loop conversion-free.
  __shared__ float smem_x[kSmemXElems];
  __shared__ float smem_w[kSmemWElems];

  Tensor sX = make_tensor(
      make_smem_ptr(smem_x),
      make_shape(Int<kInChannels>{}, Int<kTileIH>{}, Int<kTileIW>{}),
      make_stride(Int<kTileIH * kTileIW>{}, Int<kTileIW>{}, Int<1>{})
  );

  Tensor sW = make_tensor(
      make_smem_ptr(smem_w),
      make_shape(Int<kOutChannels>{}, Int<kInChannels>{}, Int<kKernel>{}, Int<kKernel>{}),
      make_stride(Int<kInChannels * kKernel * kKernel>{},
                  Int<kKernel * kKernel>{},
                  Int<kKernel>{},
                  Int<1>{})
  );

  // Cooperatively load the input halo tile.
  for (int idx = tid; idx < kSmemXElems; idx += kThreads) {
    const int c = idx / (kTileIH * kTileIW);
    const int rem = idx - c * (kTileIH * kTileIW);
    const int ih = rem / kTileIW;
    const int iw = rem - ih * kTileIW;

    const int global_h = out_h0 + ih;
    const int global_w = out_w0 + iw;

    float value = 0.0f;
    if ((unsigned)global_h < (unsigned)height_in &&
        (unsigned)global_w < (unsigned)width_in) {
      value = __bfloat162float(mX(c, global_h, global_w));
    }
    sX(c, ih, iw) = value;
  }

  // Cooperatively load all convolution weights.
  for (int idx = tid; idx < kSmemWElems; idx += kThreads) {
    const int co = idx / (kInChannels * kKernel * kKernel);
    int rem = idx - co * (kInChannels * kKernel * kKernel);
    const int ci = rem / (kKernel * kKernel);
    rem -= ci * (kKernel * kKernel);
    const int kh = rem / kKernel;
    const int kw = rem - kh * kKernel;

    sW(co, ci, kh, kw) = __bfloat162float(mW(co, ci, kh, kw));
  }

  __syncthreads();

  int local_h[kPixelsPerThread];
  int local_w[kPixelsPerThread];
  int global_out_h[kPixelsPerThread];
  int global_out_w[kPixelsPerThread];
  bool valid[kPixelsPerThread];

  #pragma unroll
  for (int i = 0; i < kPixelsPerThread; ++i) {
    const int pixel = tid + i * kThreads;
    local_h[i] = pixel / kTileOW;
    local_w[i] = pixel - local_h[i] * kTileOW;
    global_out_h[i] = out_h0 + local_h[i];
    global_out_w[i] = out_w0 + local_w[i];
    valid[i] = (global_out_h[i] < height_out) && (global_out_w[i] < width_out);
  }

  // Two output channels are computed together so each shared-memory input
  // value feeds two FMAs, while weights remain in registers.
  for (int co0 = 0; co0 < kOutChannels; co0 += kOutChannelBlock) {
    float wreg[kOutChannelBlock][kInChannels][kKernel][kKernel];

    #pragma unroll
    for (int cb = 0; cb < kOutChannelBlock; ++cb) {
      #pragma unroll
      for (int ci = 0; ci < kInChannels; ++ci) {
        #pragma unroll
        for (int kh = 0; kh < kKernel; ++kh) {
          #pragma unroll
          for (int kw = 0; kw < kKernel; ++kw) {
            wreg[cb][ci][kh][kw] = sW(co0 + cb, ci, kh, kw);
          }
        }
      }
    }

    float acc[kPixelsPerThread][kOutChannelBlock];

    #pragma unroll
    for (int i = 0; i < kPixelsPerThread; ++i) {
      #pragma unroll
      for (int cb = 0; cb < kOutChannelBlock; ++cb) {
        acc[i][cb] = 0.0f;
      }
    }

    #pragma unroll
    for (int i = 0; i < kPixelsPerThread; ++i) {
      #pragma unroll
      for (int ci = 0; ci < kInChannels; ++ci) {
        #pragma unroll
        for (int kh = 0; kh < kKernel; ++kh) {
          #pragma unroll
          for (int kw = 0; kw < kKernel; ++kw) {
            const float x_value =
                sX(ci, local_h[i] + kh, local_w[i] + kw);

            #pragma unroll
            for (int cb = 0; cb < kOutChannelBlock; ++cb) {
              acc[i][cb] = fmaf(x_value, wreg[cb][ci][kh][kw], acc[i][cb]);
            }
          }
        }
      }
    }

    #pragma unroll
    for (int cb = 0; cb < kOutChannelBlock; ++cb) {
      #pragma unroll
      for (int i = 0; i < kPixelsPerThread; ++i) {
        if (valid[i]) {
          mY(co0 + cb, global_out_h[i], global_out_w[i]) =
              __float2bfloat16_rn(acc[i][cb]);
        }
      }
    }
  }
}

torch::Tensor conv2d_bf16_k3_cin3_forward(torch::Tensor x, torch::Tensor weight) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kBFloat16, "x must be bfloat16");
  TORCH_CHECK(weight.scalar_type() == at::kBFloat16, "weight must be bfloat16");
  TORCH_CHECK(x.dim() == 4, "x must have shape [N, C, H, W]");
  TORCH_CHECK(weight.dim() == 4, "weight must have shape [C_out, C_in, KH, KW]");

  const int64_t batch = x.size(0);
  const int64_t in_channels = x.size(1);
  const int64_t height_in = x.size(2);
  const int64_t width_in = x.size(3);

  TORCH_CHECK(in_channels == kInChannels, "Only 3 input channels are supported");
  TORCH_CHECK(weight.size(0) == kOutChannels, "Only 32 output channels are supported");
  TORCH_CHECK(weight.size(1) == kInChannels, "weight.size(1) must be 3");
  TORCH_CHECK(weight.size(2) == kKernel && weight.size(3) == kKernel,
              "Only 3x3 kernels are supported");
  TORCH_CHECK(height_in >= kKernel && width_in >= kKernel,
              "Input spatial dimensions must be at least 3");

  const int64_t height_out = height_in - kKernel + 1;
  const int64_t width_out = width_in - kKernel + 1;

  auto x_c = x.contiguous();
  auto weight_c = weight.contiguous();
  auto y = torch::empty({batch, kOutChannels, height_out, width_out}, x.options());

  const int64_t x_batch_stride =
      (int64_t)kInChannels * height_in * width_in;
  const int64_t y_batch_stride =
      (int64_t)kOutChannels * height_out * width_out;

  const __nv_bfloat16* x_ptr =
      reinterpret_cast<const __nv_bfloat16*>(x_c.data_ptr());
  const __nv_bfloat16* w_ptr =
      reinterpret_cast<const __nv_bfloat16*>(weight_c.data_ptr());
  __nv_bfloat16* y_ptr =
      reinterpret_cast<__nv_bfloat16*>(y.data_ptr());

  dim3 block(kThreads);
  dim3 grid(
      (unsigned)((width_out + kTileOW - 1) / kTileOW),
      (unsigned)((height_out + kTileOH - 1) / kTileOH),
      (unsigned)batch
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_bf16_k3_cin3_kernel<<<grid, block, 0, stream>>>(
      x_ptr,
      w_ptr,
      y_ptr,
      (int)height_in,
      (int)width_in,
      (int)height_out,
      (int)width_out,
      x_batch_stride,
      y_batch_stride
  );

  cudaError_t err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess,
              "conv2d_bf16_k3_cin3_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
