            in_channels=3,
            out_channels=32,
            kernel_size=3,
            bias=False,
            dtype=torch.bfloat16,
        )

    def forward(self, x):
        return conv_ext.conv2d_bf16_k3_cin3_forward(x, self.conv1.weight)

